quests[61879] = { id = 61879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes Will Fall", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61880] = { id = 61880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honored Attendance", description = "It is my humble honor to be the Ember Court's first guest.\n\nPlease inform Prince Renathal and all of your other compatriots that I will certainly attend whenever you wish to open the gates.", completion = "If Kassir is coming, we had better ensure this is a formal affair.", objectives = "Inform Temel that Cryptkeeper Kassir will attend the Ember Court.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61882] = { id = 61882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Formal Entertainment", description = "The Accuser will be pleased that you have chosen such humble and formal entertainment for the first Ember Court.\n\nI look forward to the occasion.", completion = "Ancient rituals? This is my kind of party!", objectives = "Inform Temel that you have secured entertainment for the Ember Court.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61883] = { id = 61883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resilient Survivors", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61884] = { id = 61884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Formal Refreshments", description = "Tubbins's tea ready soon. Go tell Theotar and friends.\n\nTubbins is best!", completion = "Tubbins had better bring Gubbins along. He's the fun one!", objectives = "Inform Temel that you have secured refreshments for the Ember Court.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61885] = { id = 61885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyegor's Special Friends", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61886] = { id = 61886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mind Games of Addius", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61892] = { id = 61892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court Ambassador", description = "Expanding your influence is quite simple.\n\nFind someone. Ask them what they want. Give it to them.\n\nCongratulations. You now have influence with them.\n\nIf we wish to engage the other realms and win them over to our side, we must do the same on a larger scale.\n\nSo go to the other realms. Give them what they want. Expand our influence.", completion = "Our contacts in the other realms have already reported positive chatter surrounding your actions there.\n\n<Lady Ilinca smiles.>\n\nOur influence grows.", objectives = "Complete World Quests across the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
