quests[61895] = { id = 61895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court Ambassador", description = "Expanding your influence is quite simple.\n\nFind someone. Ask them what they want. Give it to them.\n\nCongratulations. You now have influence with them.\n\nIf we wish to engage the other realms and win them over to our side, we must do the same on a larger scale.\n\nSo go to the other realms. Give them what they want. Expand our influence.", completion = "Our contacts in the other realms have already reported positive chatter surrounding your actions there.\n\n<Lady Ilinca smiles.>\n\nOur influence grows.", objectives = "Complete World Quests across the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61896] = { id = 61896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undercover Security", description = "Do you know why the venthyr carve stoneborn into different shapes?\n\nBecause diversity in form allows for diversity in strategy. Our different shapes give us different purpose.\n\nWe need a new shape to solidify our court defenses.\n\nWith the right training and tools, venthyr guards could be hidden in plain sight--posed as greeters.\n\nAble to be among the guests without raising concerns, they'd be the first to respond to active threats.", progress = "Undercover guards? Interesting idea...", completion = "This was the easy part. The hard part will be finding guards who want to listen to socialites prattle for hours on end.", objectives = "Collect The Everyday Assassin training guide from Maldraxxus and 20 Enchanted Trickster Dust from Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61898] = { id = 61898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Bites", progress = "Are you sure Picky Stefan wanted ALL of these things?", completion = "I never understand you mortals' fascination with cheese... It looks disgusting.\n\nBut Picky Stefan gets what Picky Stefan wants!", objectives = "Collect cheeses from Bastion and Sourbread Yeast Starter from Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61899] = { id = 61899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Tastings", progress = "That's a whole lot of anima you got there. That's all just for drinking?", completion = "Hips already sent over a name for the Master of Anima he wants to lead the tastings.\n\nI'll get her on the staff and have this stuff delivered to her.", objectives = "Collect fresh anima from Ardenweald, Bastion, Maldraxxus, and Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61900] = { id = 61900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Comfy Chairs", description = "I want guests to sit.\n\nStanding is hard. I know 'cause I stand a lot.\n\nGuest should sit and be comfy.\n\nI make comfy chairs for all guests to sit.\n\nGuests be happy, stay longer!", progress = "Boot knows his stuff. If he says we should make chairs, we should make chairs.", completion = "<Temel can't stop himself from feeling the soft vulpin fur.>\n\nOoo, these chairs are going to be so comfortable!", objectives = "Collect 30 Soft Vulpin Fur from Bastion and 30 Reclaimed Wood from Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61916] = { id = 61916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Fire Damage", progress = "Decorations not ready!\n\nLast Ember Court, those big fires from candles burn all the tablecloths.\n\nBring me pretty cloth and I make new tablecloths.\n\nThen we can pick decorations for next court.", completion = "This good cloth. Will dip in muck to make fire-proof.\n\nDecorations be ready for you now!" }
quests[61943] = { id = 61943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Court Influencer", objectives = "Your investments into the Ember Court have allowed me to compile this list of potential new guests we could invite.\n\nPlease, browse them at your convenience and inform me who we should extend an invitation to first.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61944] = { id = 61944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discerning Taste", objectives = "Your investments into the Ember Court have attracted the attention of some very powerful individuals, {name}.\n\nI have compiled a list of these exclusive guests. Review them at your convenience and inform me who you wish to extend an invitation to first.\n\nFair warning, these discerning individuals will not be as easy to please.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61945] = { id = 61945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Professionals", completion = "Phew, those professionals know how to get a job done!\n\nI'll make sure they're at every Ember Court from now on, you just gotta swing by and give them orders before the gates open.", objectives = "Enter the Ember Court, then give orders to one of the specialist staff members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61946] = { id = 61946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natural Defenders", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
