quests[61949] = { id = 61949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ardenweald's Tricksters", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61950] = { id = 61950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting the Wilds", description = "The supply of attuned anima is running low again. I'm surprised that we've managed to stretch our resources so far without a resupply.\n\nYou've proven yourself proficient at tracking down what is needed, perhaps you could assist us once again?\n\nThe runestags that roam Ardenweald's forests are particularly suffused with the power of the wilds, anima retrieved from them will be optimal for our needs.\n\nGood hunting!", progress = "Worry not about the runestags, after some time they will return. This is just one part of the eternal cycle.", completion = "Good job! Your efforts will go a long way to keeping our production moving ahead.\n\nThank you!", objectives = "Collect 10 Feral Anima from Runestags.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61957] = { id = 61957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ashraka", objectives = "My services are now yours Maw Walker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61958] = { id = 61958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Gorgelimb", objectives = "New master now!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61959] = { id = 61959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Talethi", objectives = "I shall pay my debt to my Maw Walker.\n\nDirect my power against your enemies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61960] = { id = 61960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Xertora", objectives = "Do you happen to have a spare leg lying around? Surely you don't need two. I'll put it to good use, kicking your enemies!\n\nNo? I can probably still help anyway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61961] = { id = 61961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Rattlebag", objectives = "I am prepared for combat!\n\nPut me in the front line, I will be your shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61962] = { id = 61962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Velkein", objectives = "I shall wield my blade with purpose once more!\n\nDeath to your enemies!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61963] = { id = 61963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Called to the Hunt", description = "The Wild Hunt is made up of fae who have dedicated their lives to the protection of Ardenweald and its denizens. Each member has skill sharp as a blade and sense unlike no other.\n\nWe have spoken to a duo, an evoker and a huntress, who will permit us to capture their memories for training if we help them on a particular hunt.\n\nMeet Alderyn in Claw's Edge. He is one you seek.", progress = "You are not of these lands. How may I aid you?", completion = "The envoy of the kyrian, armed with the perfect weapon to pierce our quarry's armor.\n\nAre you ready for a hunt?", objectives = "Find Alderyn in Claw's Edge in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61964] = { id = 61964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aubrie Weekly Jailers Tower Quest" }
quests[61965] = { id = 61965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piercing the Shell", description = "Our quarry is one of the gorm, native creatures who were once helpful beasts of the realm, until the drought drove them mad.\n\nThis particular beast has not only grown to a frightening size, but also has a shell so strong that none of our weapons or arrows have managed to pierce it.\n\nThis spear you bring, infused with the anima of Bastion, could be the exact weapon we need to pierce the gorm's armor and put him down.\n\nMy sister went ahead to scout. Let's not linger.", completion = "The terror has been put down. Your aid, and your spear, were quite useful.", objectives = "Find Myn'ir in the Gormhive, then kill the Fortified Desiccator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61967] = { id = 61967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remedial Lessons" }
quests[61968] = { id = 61968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Wing It", description = "For untold ages, the humble Ardenmoth has supplied the scales for the creation of armor for the Wild Hunt. \n\nNow, with our attention divided between the threats to the realm and the anima drought, it has become increasingly difficult for our foragers to find the perfect scales that we require.\n\nOnly the scales of the highest quality are suitable. If you should obtain any in your travels and return with them, I shall ensure you are well rewarded.", progress = "Have you the scales?", completion = "Ah, remarkable quality! You've done well!", objectives = "Collect 28 Perfect Ardenmoth Wing Scales from Ardenmoths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61981] = { id = 61981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Replenish the Reservoir", description = "Right, here's the gig: we need anima.\n\nNot just a bit or a pinch, but a lot. See, anythin' worth doin' can't be done without anima. Not in the Shadowlands. Not if we are gonna fix this mess Denathrius got us in.\n\nSo, we need your increasin'ly resourceful self to beg, borrow, steal, nick, burglarize, pulverize, pirate-ize, earn, swindle, or otherwise become the source of a great charity of any anima you can get.\n\nBring it to me, an' I'll stock our coffers, as it were, so you can put it to use.", progress = "How goes the anima hunt? You pinch us a pint or boost us keg?", completion = "Now that's a right grey professional job that is. This anima will get us makin' some fancy stuff in no time.", objectives = "Collect anima sources for the Anima Reservoir at Sinfall in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61982] = { id = 61982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Replenish the Reservoir", description = "Hail, Maw Walker.\n\nAs our influence over Bastion grows, so too does our need for our most precious resource--anima.\n\nWe must replenish our reserves. Scour the realms for all that you can find and return here with the anima. \n\nWith our precious reserves replenished, we can direct the anima wherever it is needed most.\n\nGo in service, {class}.", progress = "Every drop of anima is a gift in these times.", completion = "You have my thanks, Maw Walker. We will not let it go to waste.", objectives = "Collect anima sources for the Anima Reservoir at Elysian Hold in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61983] = { id = 61983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Replenish the Reservoir", description = "We require your strength, Maw Walker.\n\nThe houses of our enemies grow stronger by the hour. In order to press the attack we must find new sources of anima to bolster our reserves.\n\nSearch the realms for this precious resource and bring it back here to the Sanctum. Let none deny you!\n\nWith your help the rival houses shall fall, one by one, and we will emerge victorious!", progress = "The march to victory will require more anima.", completion = "Your contributions fuel our conquests on the battlefield. The final victory will be ours!", objectives = "Collect anima sources for the Anima Reservoir at Seat of the Primus in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61984] = { id = 61984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Replenish the Reservoir", description = "Greetings, Maw Walker.\n\nThe Tirna Achiad, Heart of Ardenweald, flourishes in our care, yet more anima is needed for our Sanctum.\n\nThe cycle of rebirth, our purpose, must continue.\n\nTo help our Queen, we must acquire more. Will you help us replenish the reservoir?", progress = "Have you come to dedicate anima to our sacred purpose?", completion = "The anima you have provided will nourish our precious groves. We thank you.", objectives = "Collect anima sources for the Anima Reservoir at the Heart of the Forest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61985] = { id = 61985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wake The Sleepers", description = "The land speaks to me, {name}. Ardenweald is a realm of cycles, but it has never faced an anima drought such as this.\n\nWe will need the aid of all who reside here if we are to make it through this crisis.\n\nMany souls slumber within the forests and hills. If they can provide us some of their anima, we may be able to endure a little longer. Should you encounter any of the souls in your travels, please awaken them and send them to me.", completion = "This dew will help our craftmasters a great deal!\n\nThank you, little one.", objectives = "Awaken 8 Slumbering Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61996] = { id = 61996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Say The Magic Words", description = "Ever since I cast my first spell, I've not been able to get enough of magic!\n\nIt's not as hard as all those liches say it is. You focus your thoughts, say the words, and magic starts happening!\n\nThere are tomes documenting ancient spells stored in the Archivam of Revendreth. Help me gather them so I can learn some new spells!", completion = "You have helped strengthen our forces, Maw Walker.", objectives = "Help Sabrina learn 12 new spells in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61998] = { id = 61998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of Stone", progress = "We got room for another big statue on this here spot.\n\nYou get me some stone and I'll make whatever kind of statue you want, yeah?\n\nMaybe one of you, or someone else, yeah?", completion = "Tell me what kind of sculpture you want me to make!" }
quests[62000] = { id = 62000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choosing Your Purpose", description = "Each covenant is vital to the Shadowlands. Though they have been isolated and divided as of late, the Purpose depends on the success of their efforts.\n\nAll of the covenants must bolster their strength to face the threat of the Banished One. But your contributions cannot be divided. They must be focused upon a single path. Other mortals may make a different choice.\n\nSpeak to your potential allies. Then make your choice at the map of the Shadowlands before me.", progress = "Have you made your decision?", completion = "All is as expected. Trust always in the Arbiter's wisdom.", objectives = "Speak to the Covenants. Decide how your path is entwined with the Purpose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62041] = { id = 62041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In A Bad Light", description = "I've heard about the chaos in Revendreth. Reports of exiles driven mad and burned in the Desiccation. \n\nThe very thought of all that suffering fills me with the urge to do something about it.\n\nIf you are headed there, please let me accompany you. I simply must help as many as I can!", progress = "Did we cure them all?", completion = "Suffering is commonplace among those in Revendreth, but you and Roseboil were able to help a few of them nonetheless. \n\nWell done.", objectives = "Use Roseboil's Regenerative Molt to cure 15 Light-Seared Exiles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62043] = { id = 62043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove Your Worth", description = "You must prove your worth to us again {name}.\n\nWe have not forgotten your betrayal.\n\nYet you say you seek penance. This task will start to demonstrate that you are serious about earning back our trust.", completion = "So, you have done as we ask and are ready to rejoin our ranks?\n\nOnce you complete this task with me you will leave your current Covenant and rejoin the Kyrian.", objectives = "Complete the task for the Kyrian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62044] = { id = 62044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standing Toe To Toe", description = "<The gorger is clearly bigger, it gestures with its head towards one of the other gorgers as if urging you to attack it.>", progress = "Attack and defeat devourer gorgers in the Endmire.", completion = "<There is little expression you can see on the gorger's 'face' but it appears as if it is very full of itself as if it defeated them on its own. It does offer you a shiny thing it found.>", objectives = "Defeat devourer gorgers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62045] = { id = 62045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready for More", description = "<Again the gorger is strutting ready for more fighting, staring down the the closest gorger.>", progress = "Attack and defeat devourer gorgers in the Endmire.", completion = "<Head high the gorger is really strutting his stuff and is clearly thinking you make a great team. He looks up at you ... and he spits up something that he thinks you might like.>", objectives = "Defeat devourer gorgers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62046] = { id = 62046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Pack", description = "<The gorger is more than fully grown, rivaling most of the other devourers in the area. It clearly wants to stay with you, but it appears to be uneasy straying too far from the world eaters. Maybe if you take one down together it will not hold as much sway over the gorger.>", progress = "<The gorger gestures in the direction of a worldeater, seemingly feeling up to the challenge with you by its side.>", completion = "<The gorger is ecstatic that you took down a worldeater. It's excitement is palpable and it is on the brink of picking you up and carrying out off on a new adventure.>", objectives = "Defeat an Unbidden Worldeater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62051] = { id = 62051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormling Toss: Spirit Glen" }
quests[62052] = { id = 62052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exiled by Paranoia", description = "The liches of the House of Rituals were an instrumental piece in the Maldraxxi attack on Bastion. They are not currenty our allies, and it would be difficult to convince one to let us capture their memory for our training purposes.\n\nWe have made contact with a necromancer who has a score to settle with one of the liches. Find her and she will aid you in capturing this memory.", progress = "<Karaxi is sifting through a book very carefully.>", completion = "My plan is truly coming to fruition. An outsider, here to help me enact my revenge!", objectives = "Find Karaxi the Defector in the Challenger's Promenade in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62053] = { id = 62053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necromantic Power", description = "My old master, Thran'tiok, is the epitome of paranoia. She believes everybody will turn on her, and it led to my exilement from not only her service, but the House of Rituals as a whole.\n\nI had no intent to cross her... but that has changed.\n\nTake the crystal casing you have built and slay my old colleagues to infuse it with necromantic energy. It shall lead you to Thran'tiok's phylactery, which should be exactly what we both seek.", progress = "Thran'tiok thinks I am a threat...\n\nI will show her what that word truly means.", completion = "We do not have much time. Thran'tiok will appear herself soon.", objectives = "Charge the Soulseeker Crystal by defeating foes in the House of Rituals, then use it to find Thran'tiok's phylactery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62054] = { id = 62054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Castle Nathria: Getting a Head", description = "We need to show Denathrius that we mean business. His dredger... pet... should do the trick.\n\nBring me his head. Four times should do it. Dredgers are curious creatures.", progress = "I need the heads or we cannot make a profound statement.", completion = "With these I'm certain we'll catch the attention of Sire Denathrius.", objectives = "Collect 4 Sludgefist's Head from Sludgefist within Castle Nathria on Normal Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62055] = { id = 62055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Castle Nathria: Getting a Head", description = "We need to show Denathrius that we mean business. His dredger... pet... should do the trick.\n\nBring me his head. Four times should do it. Dredgers are curious creatures.", progress = "I need the heads or we cannot make a profound statement.", completion = "With these I'm certain we'll catch the attention of Sire Denathrius.", objectives = "Collect 4 Sludgefist's Head from Sludgefist within Castle Nathria on Heroic Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62056] = { id = 62056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Castle Nathria: Getting a Head", description = "We need to show Denathrius that we mean business. His dredger... pet... should do the trick.\n\nBring me his head. Four times should do it. Dredgers are curious creatures.", progress = "I need the heads or we cannot make a profound statement.", completion = "With these I'm certain we'll catch the attention of Sire Denathrius.", objectives = "Collect 4 Sludgefist's Head from Sludgefist within Castle Nathria on Mythic Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62057] = { id = 62057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Who Hunger", description = "I've heard reports that the number of gorm sightings have risen greatly the past few days.\n\nNormally they're simple decomposers, playing their part in the great cycle, but in great numbers the gorm can be aggressive. If left unchecked, their ravenous hunger will cause untold destruction.\n\nThe Wild Hunt has called for a gorm hunt. Meet your quota and you will be well-rewarded.", completion = "Ah, good work. The gorm serve their purpose, but as in all things, balance must be maintained.", objectives = "Destroy 20 Gorm in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62058] = { id = 62058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Centurions, Assemble!" }
quests[62059] = { id = 62059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove Your Worth", description = "You must prove your worth to us again {name}.\n\nWe have not forgotten your betrayal.\n\nYet we know you seek penance. This task should prove your willingness to rejoin our ranks.", completion = "So, you have done as we ask and are ready to rejoin our ranks?\n\nOnce you complete this task with me you will leave your current Covenant and rejoin the Necrolords.", objectives = "Complete the task for the Necrolords.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62060] = { id = 62060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove Your Worth", description = "You must prove your worth to us again {name}.\n\nWe have not forgotten your betrayal.\n\nYet we know you seek penance. This task should prove your willingness to rejoin our ranks.", completion = "So, you have done as we ask and are ready to rejoin our ranks?", objectives = "Complete the task for the Night Fae.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62061] = { id = 62061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove Your Worth", description = "You must prove your worth to us again {name}.\n\nWe have not forgotten your betrayal.\n\nYet we know you seek penance. This task should prove your willingness to rejoin our ranks.", completion = "So, you have done as we ask and are ready to rejoin our ranks?", objectives = "Complete the task for the Venthyr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62062] = { id = 62062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Stolen Rugs", progress = "Decorations not ready!\n\nLast Ember Court, those thieves steal more than memories. They steal rugs too!\n\nNew rugs be so heavy thieves can't carry! Bring me things to make heavy rugs.\n\nThen we can pick decorations for next court.", completion = "Ha! New rugs be heavy and pretty... just like me.\n\nDecorations be ready for you now!" }
quests[62064] = { id = 62064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Broken Mirrors", progress = "Decorations not ready!\n\nLast Ember Court, those prisoners break all the mirrors when they escape!\n\nLaurent help me fix, but need pieces.\n\nThen we can pick decorations for next court.", completion = "With mirrors fixed, I can see my pretty face again.\n\nDecorations be ready for you now!" }
quests[62065] = { id = 62065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: My Favorite Table", progress = "Decorations not ready!\n\nLast Ember Court, one of them big bad dredgers sit on my favorite table, break in half!\n\nNeed wood to fix table.\n\nThen we can pick decorations for next court.", completion = "I make sure no big bad dredgers sit on my table again.\n\nDecorations be ready for you now!" }
quests[62066] = { id = 62066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Dredger Pool", progress = "Decorations not ready!\n\nLast Ember Court, that big slimeball leaked slimeball slime into our muckpool. Every new dredger all slimy!\n\nNeed way to get rid of all bad stuff... You know thing does that?\n\nThen we can pick decorations for next court.", completion = "Okay... I pour into muckpool and see if helps.\n\nDecorations be ready for you now!" }
quests[62067] = { id = 62067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Statues", progress = "Decorations not ready!\n\nLast Ember Court, dredgers see big new statue made. All want statues now!\n\nBring me stone and I carve tiny statues to hold. Make all dredgers happy.\n\nThen we can pick decorations for next court.", completion = "Maybe I carve for prince too. He like statues, yeah?\n\nDecorations be ready for you now!" }
quests[62068] = { id = 62068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormling Piper: Crumbled Ridge" }
quests[62069] = { id = 62069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Sinstones", progress = "We got a problem, {name}.\n\nLast Ember Court, the Accuser's rituals were a little TOO convincing. A bunch of my dredgers want their own sinstones now, so they can list things they think they've done wrong.\n\nI'm going to need some resources to soothe their guilty consciences.\n\nThen we can pick our entertainment for the next Ember Court.", completion = "I can't believe we're doing this... But I am curious to see what the crew writes on these.\n\nWe can book the next Entertainment whenever you're ready." }
quests[62070] = { id = 62070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Fragrant Flowers", progress = "We got a problem, {name}.\n\nLast Ember Court, some of the animals had... issues. I can't get the stains out and everything reeks!\n\nI'm going to need some very fragrant flowers to cover up this smell.\n\nThen we can pick our entertainment for the next Ember Court.", completion = "These smell great! Or at least better than the current smell...\n\nWe can book the next Entertainment whenever you're ready." }
quests[62073] = { id = 62073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Band Shirts", progress = "We got an opportunity, {name}.\n\nThe Lost Chalice Band is the hottest entertainment in Revendreth after that killer performance at the last Ember Court. It's all anyone's talking about.\n\nWe should make some band shirts, give 'em out for free to keep the hype rolling.\n\nBring me the materials and I'll take care of the rest.\n\nThen we can pick our entertainment for the next Ember Court.", completion = "Soon every socialite in Revendreth will wearing one of these, promoting our court.\n\nWe can book the next Entertainment whenever you're ready." }
quests[62074] = { id = 62074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Professions - Reuse", description = "You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver's stolen memories.", objectives = "Bring the memory back to the Runecarver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62075] = { id = 62075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Soul Cages", progress = "We got a problem, {name}.\n\nLast Ember Court, we were able to save quite of a few of those abused souls the Master's minions attacked us with. \n\nThat's great, but we need more chains and cages if we're going to keep that many souls here until the Accuser can take them.\n\nThen we can pick our entertainment for the next Ember Court.", completion = "I'll get the ritualists to help us build the cages, so they'll be done right.\n\nWe can book the next Entertainment whenever you're ready." }
quests[62076] = { id = 62076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Free Press", progress = "We got a problem, {name}.\n\nLast Ember Court, that provocateur's gossip spread further than we thought. I've gotten all sorts of uncomfortable questions from socialites and nobles unsure of what to believe.\n\nWe've got to write some pamphlets to set the record straight and dispel that scoundrel's lies!\n\nThen we can pick our entertainment for the next Ember Court.", completion = "Writing letters: one of the oldest forms of entertainment.\n\nWe can book the next Entertainment whenever you're ready." }
quests[62078] = { id = 62078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Fashion Accessories", progress = "We got a problem, {name}.\n\nLast Ember Court, the Countess's clothier showed everyone the future of fashion and we're all way behind. Medallions are all the rage, thanks to the Prince's growing collection.\n\nI can't get a medallion, but I at least need a necklace so I don't get laughed out of courts.\n\nThen we can pick our entertainment for the next Ember Court.", completion = "I can't believe I'm going to wear this gaudy necklace, but if this is what it takes to make sure we always have access to the best entertainment...\n\n<Hips sighs.>\n\nWe can book the next Entertainment whenever you're ready." }
quests[62080] = { id = 62080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Herbal Tea", progress = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, our guests drank more tea than Theotar himself! Our entire supply is depleted.\n\nI simply must acquire new tea ingredients, and I only accept the highest quality!\n\nAfter that, I shall happily discuss refreshment options for our next court.", completion = "Ah yes, these shall make a glorious tea once I have dehydrated them.\n\nNow we may discuss refreshments for our next Ember Court." }
quests[62081] = { id = 62081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Those Animacones!", description = "Reports say that once again the spriggan are proving to be a nuisance, {name}.\n\nWord is that a bunch of them broke into the stores at the Heart of the Forest and made off with a huge store of animacones.\n\nNeedless to say, we need those animacones back.\n\nThe report says the spriggan group split up as they were making their escape, so any one you see is as likely to be carrying the animacones as the next. \n\nGood luck.", progress = "Were you able to find the animacones?", completion = "You were able to retrieve all of them? Outstanding!", objectives = "Collect 44 Looted Animacones from spriggan within Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62082] = { id = 62082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Personal Stash", progress = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, while your guests were so flippantly flinging food around court, several stray pies flew directly into my personal food supplies. Everything was ruined!\n\nYou know I do not like to make a fuss, but I simply must insist that you replace the delicacies ruined by that unwelcome food fight.\n\nAfter that, I shall happily discuss refreshment options for our next court.", completion = "Thank you. All is forgiven.\n\nNow we may discuss refreshments for our next Ember Court." }
quests[62083] = { id = 62083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Medical Supplies", progress = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, those wild mushrooms you brought poisoned me and half of the socialites!\n\nThankfully, it does not appear to be a lethal poison, but it has been most uncomfortable for all involved.\n\nWe are in desperate need of anti-venom.\n\nAfter that, I shall happily discuss refreshment options for our next court.", completion = "<Picky Stefan pinches his nose and sips from the potion vial.>\n\nI have never been more eager to consume something that tastes so foul.\n\nNow we may discuss refreshments for our next Ember Court." }
quests[62084] = { id = 62084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Fine Cutlery", progress = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, the venthyr invaders did not just assault our guests--they stole our cutlery!\n\nMy old friend Forgy can craft replacement cutlery for us, but we will need to provide the supplies.\n\nAfter that, I shall happily discuss refreshment options for our next court.", completion = "The old cutlery was due to be replaced anyway.\n\nNow we may discuss refreshments for our next Ember Court." }
quests[62085] = { id = 62085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...Why Me?", description = "<The dense, chunky liquid inside the vessel emits a horrendous odor.\n\nThe initials O.K. are etched into the side. It seems someone stole Overseer Kalvaros' canteen.>", completion = "I've been wondering where my canteen went. Where did you find this, {name}? Did you take a drink before returning here?\n\nNo matter, I suppose.", objectives = "Deliver the Reclaimed Vessel to Overseer Kalvaros at the Challenger's Promenade.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62086] = { id = 62086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Professions - Reuse", description = "You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver's stolen memories.", objectives = "Bring the memory back to the Runecarver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62087] = { id = 62087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Imported Dinnerware", progress = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, the stone fiends dropped more than Theotar's tea set. They broke the dinnerware I had imported directly from Ardenweald, in order to help our Night Fae guests feel at home!\n\nI believe I can repair them, but I will need resources.\n\nAfter that, I shall happily discuss refreshment options for our next court.", completion = "I am certain that our Night Fae friends will appreciate the effort we have gone through to accommodate them.\n\nNow we may discuss refreshments for our next Ember Court." }
