quests[62094] = { id = 62094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Exploratory Meals", progress = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nYou may recall that an excess of gnats swarmed our last Ember Court. Although initially repulsed, I have begun to ponder if there might be some culinary value to these creatures.\n\nI would like to attempt a few meals with them. I shall require a few things to steel myself for the culinary adventure.\n\nAfter that, I shall happily discuss refreshment options for our next court.", completion = "Wish me luck... I fear that I shall need it.\n\nNow we may discuss refreshments for our next Ember Court." }
quests[62095] = { id = 62095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Medic's Tent", progress = "I have an urgent matter to discuss.\n\nWhile the volunteer portion of our security showed tremendous bravery at the last Ember Court, it was clear that they were unprepared for the rigors of battle. They suffered tremendous injuries.\n\nWe need to resupply our medical team to be ready for the next court.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", completion = "Thank you. Caring for the wounded is an honorable endeavor.\n\nThe full breadth of our Security options are available to us now." }
