quests[62103] = { id = 62103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Professions - Reuse", description = "You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver's stolen memories.", objectives = "Bring the memory back to the Runecarver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62104] = { id = 62104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Stoneborn Reserves", progress = "I have an urgent matter to discuss.\n\nAt the last Ember Court, many of our stoneborn suffered fractures and cracked limbs while defending our guests. We will need to repair them.\n\nBring me the stone, and I will coordinate the repairs with our dredgers.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", completion = "This should be enough to rebuild the fallen stoneborn.\n\nThe full breadth of our Security options are available to us now." }
quests[62105] = { id = 62105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Unconventional Weapons", progress = "I have an urgent matter to discuss.\n\nFighting alongside the Maldraxxi forces at the last Ember Court inspired me to strategize outside of the typical boundaries of venthyr warfare.\n\nI am certain you mortals have developed creative weapons. Bring me some, so that I may learn them.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", completion = "Interesting. I did not expect them to be so... mechanical.\n\nThe full breadth of our Security options are available to us now." }
quests[62106] = { id = 62106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Enchantments", progress = "I have an urgent matter to discuss.\n\nThe Stone Legion's surprise attack on our last Ember Court revealed that I have been far too lax in pursuing enchantments for our troops' equipment. We must use every advantage at our disposal.\n\nBring me any enchantment you can spare.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", completion = "The next time the Stone Legion invades, we'll be ready for them.\n\nThe full breadth of our Security options are available to us now." }
quests[62108] = { id = 62108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Strategic Codices", progress = "I have an urgent matter to discuss.\n\nAt the last Ember Court, the devourer's ambush tactics caught our guards by surprise. Their portals opened all around us and we were too slow to respond.\n\nWe should stock up on supplies that will allow us to adapt to changing circumstances.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", completion = "Even those made of stone can change with time.\n\nThe full breadth of our Security options are available to us now." }
quests[62109] = { id = 62109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restock: Surveillance Equipment", progress = "I have an urgent matter to discuss.\n\nAs you are aware, a murder occurred at the last Ember Court. That is an unacceptable failing on my part and I apologize.\n\nI would like to acquire additional surveillance equipment to ensure we are prepared if it happens again.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", completion = "I tolerate many questionable activities in the court, but murder will not be one of them.\n\nThe full breadth of our Security options are available to us now." }
