quests[62147] = { id = 62147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Party Pests" }
quests[62148] = { id = 62148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Raining Anima" }
quests[62155] = { id = 62155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runestone Roundup", description = "Stone is a rare material in Ardenweald. Yet, I've heard tales that those who were masked by the Drust have small stones upon them.\n\nI'd like you to retrieve some of these stones for the Wild Hunt, so that we may better understand their link to our enemy.\nFace the masked and collect the stones from their deceased forms and I'll compensate you for your efforts.\n\nIt's a gruesome task, but one that must be done.", progress = "How goes your investigation?", completion = "You were able to retrieve all of them? Outstanding!", objectives = "Collect 18 Runestone Spikes from drust possessed fae within Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62157] = { id = 62157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting from a Safe Distance", description = "The resurgence of the Scourge is troubling enough, but there are also reports that the Cult of the Damned has risen anew as well.\n\nIf true, then that bodes ill for us all. We cannot allow the cultists' machinations to continue unchecked.\n\nI suggest we engage in some reconnaissance.", progress = "Notice anything unusual?", completion = "They must be planning something. Though what, I cannot say.\n\nI will instruct our scouts to observe and report.", objectives = "Survey the Cult of the Damned's presence at Aldur'thar and Mord'rethar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62159] = { id = 62159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Shadowlands", description = "There is much to do within the Shadowlands. Many areas are suffering from the anima drought.\n\nThe choice of who to help first is yours. Where will you go?", completion = "This is your first step towards thwarting the Jailer.", objectives = "Choose where to go in the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62160] = { id = 62160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bundle of Lilies", description = "This grove needs something special, something to make it really stand out.\n\nI have a plan, but first I need flowers.\n\nNot just any flowers, but Night Lillies. They have a sweet scent that evokes starlit nights spent standing on a hilltop overlooking the majesty of the land.\n\nAs you go exploring Ardenweald, look to the waterways for Night Lillies growing in the waterways and collect them.\nI will pay you for your efforts, of course.", progress = "Were you able to find any of the lillies?", completion = "Ah, their scent is lovely!\n\nHaving a few of these placed around the grove will greatly help with morale.", objectives = "Collect 10 Night Lillies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62161] = { id = 62161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood from a Bone", description = "I want nothing more than to make for Revendreth immediately... but it seems they have their own challenges to face.\n\nAll know of the mark we left on Bastion. The venthyr are sure to be wary of allowing us into their realm.\n\nOnce again, we must turn to you. Your renown across the Shadowlands has earned you the trust of many. Now, we need the trust of Revendreth.", completion = "You're just in time. I've received a missive.", objectives = "Increase your Renown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62162] = { id = 62162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message from the Justicar", description = "Justicar Trueheart has sent a personal request for your immediate assistance, {name}.\n\nThe frozen winds of Icecrown await your return.", completion = "I am glad for your return, {name}.", objectives = "Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62163] = { id = 62163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message from the Justicar", description = "Justicar Trueheart has sent a personal request for your immediate assistance, {name}.\n\nThe frozen winds of Icecrown await your return.", completion = "I am glad for your return, {name}.", objectives = "Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62165] = { id = 62165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal-Inara's Call", description = "Your presence is needed within the Enclave.\n\nIt is time for you to choose a covenant to ally yourself with.", sourceObjective = "Meet Tal-Inara within the Enclave in Oribos.", sourceObjectiveStatus = "unverified-source-field" }
quests[62166] = { id = 62166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal-Inara's Call", description = "Your presence is needed within the Enclave.\n\nIt is time for you to choose a covenant to ally yourself with.", sourceObjective = "Meet Tal-Inara within the Enclave in Oribos.", sourceObjectiveStatus = "unverified-source-field" }
quests[62168] = { id = 62168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonescript Dispatches" }
quests[62169] = { id = 62169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes to the Sky", description = "The House of Eyes still reels from Akarek's demise. They search for direction. For purpose.\n\nPerhaps you can help them find it. Continue to gain the trust of the Eyes. Their skills will be invaluable to our cause.", completion = "You've done well, Maw Walker. The Eyes place their trust in you.", objectives = "Increase your Renown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62170] = { id = 62170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You'll Never Walk Alone", description = "<You have stumbled upon some messy notes. Some of the lines seem incomprehensible while others seem melodic.>\n\nLike wind and rain, discord storms my mind, tossing and blowing.\n...\nI must find the golden skies.\n...\nRemember, walk on, heart full of hope, and you'll never walk alone.\n\n<It seems as though an aspirant cannot find their way home. You should inform someone at Hero's Rest.>", completion = "Ah, these wise words are certainly Eurgon's. I'm happy to report he made it home.", objectives = "Turn these notes in to Inkiep in Hero's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62171] = { id = 62171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tea Time" }
quests[62172] = { id = 62172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shortsleeved Doublet", progress = "Is that a slightly worn doublet for me!", completion = "Thank you! I will put this away until the time is right to wear it." }
quests[62173] = { id = 62173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Long Sleeved Doublet", progress = "<Your dredger reaches out enthusiastically for the long sleeved doublet.>", completion = "Oooh, it has sleeves that go past my elbows, thank you! I can't wait until we find the right time to wear it." }
quests[62174] = { id = 62174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Cover", progress = "<Your dredger butler eyes you as if not sure if you are giving him the coif, or just asking him to hold it for you.>", completion = "Is that a cap for me? It is so floppy, I love it! And it will go around my ears!" }
quests[62175] = { id = 62175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking Fabulous", progress = "Who is this? Oh, look at those flowing locks...", completion = "<Your butler shakes his head back and forth imagining the flowing locks in the portrait.>\n\nOooh, thanks, I am sure we could find a good time to cut my hair like this!" }
quests[62176] = { id = 62176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spikey Look", progress = "That creature has a very distinct look...", completion = "I bet if I curled into a ball using it the spikes would be pretty scary, not that I would think of doing anything like that at a party, unless we could use that... I will just save this poster for when the time is right for this cut." }
quests[62177] = { id = 62177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Memorable Look", progress = "Oh, I have seen this dredger before!", completion = "Ooh, this look feels fitting for a role like mine, I am sure many other dredgers have assisted while sporting this sparse, scraggly look. I can't wait to try it out!" }
quests[62178] = { id = 62178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Muck Dye", progress = "Another muck dye!", completion = "Ah, black muck, it stains the fingers, but is very distinguished. I will save this for the next time we need to dye my doublet. I want to remind you that we will need one for each dying, but I can keep this one ready." }
quests[62179] = { id = 62179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blue Muck Dye", progress = "Isn't muck so versatile!", completion = "Do you think the blue muck looks like the sky? Dirk thought it did, but I don't think so. I will save this for the next time we need to dye my doublet. I want to remind you that we will need one for each dying, but I can keep this one ready." }
quests[62180] = { id = 62180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green Muck Dye", progress = "There are so many muck colors, how do you choose just one?", completion = "I have only visited the Banewood Muck Pool once, but I found it was a bit crowded myself, I definitely prefer working solo. I will save this for the next time we need to dye my doublet. I want to remind you that we will need one for each dying, but I can keep this one ready." }
quests[62181] = { id = 62181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bubbling Red Muck Dye", progress = "Is that one still bubbling?", completion = "Ooh, its still warm. I could live out in the Ember Ward. I will save this for the next time we need to dye my doublet. I want to remind you that we will need one for each dying, but I can keep this one ready." }
quests[62182] = { id = 62182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Letter From Nadja", description = "The letter is addressed to Nadja's contact Dimwiddle in Darkhaven. It is clearly sealed with Nadja's mark. It is certainly of great import, you should make sure the letter is delivered.", completion = "Uh, what can Dimwiddle do for you? Oh, a letter... <Dimwiddle sees Nadja's mark and his eyes go wide> yes, thank you I have been awaiting that letter. It's from my aunt <Dimwiddle winks at you> she has been ill. I will make sure to tell everyone you helped deliver important letters!", objectives = "Return the letter to Darkhaven.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62183] = { id = 62183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Leaking Box Marked Perishable", description = "A very exact entity wanted this package to reach Ta'tru at the Night Market. It looks like Broker script. The package is clearly leaking, and it is marked perishable. Perhaps delivering it quickly would be best.", completion = "Ooh, is that my package of flesh-eating ooze?! I hope you did not get any on your hands. Wearing gloves while handling this particular ooze should mean you have only a 25% chance of suffering an adverse effect. The gloves may be burned, but I will leave that to your discretion. I will inform the locals of your assistance in delivery, even if it was delayed.", objectives = "Deliver the package to the Night Market.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62184] = { id = 62184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crate of Sinvyr Ore", description = "The crate is fairly big and looks heavy, but it also looks like something someone would be willing to compensate for. Take the crate to Gibbo at the Old Gate. He should be expecting the recurring shipment.", completion = "Finally! What have you been doing with that shipment? You are a week late and now I am behind. <He sees you starting to talk and carries on.> No, I don't want to hear it. I won't be giving you a good review for this delivery, but here is the arranged cut of the shipment.", objectives = "Deliver the crate to the Old Gate.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62185] = { id = 62185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting for Attention", description = "Maintaining a watchful eye on the Cult of the Damned has proven challenging... and perilous.\n\nSeveral of our hippogryph riders recently ran afoul of the cult's winged terrors. Though a few were able to escape, the others were captured and brought to Aldur'thar.\n\nDo what you can to free them from their captors. We cannot afford to lose any more of our forces.", completion = "You have my gratitude.\n\nI assure you this will not be forgotten.", objectives = "Free 5 Argent Hippogryph Riders from Aldur'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62186] = { id = 62186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swollen Anima Seed", description = "The masked sylvar set aside a single seed laden with anima; for what purpose, you can only imagine. Droman Tashmur would appreciate the return of such a precious resource.", completion = "What have you brought me? Why would the masked ones be collecting anima so? A concern for the future. Thank you for bringing this to me. It will nourish many wildseeds.", objectives = "Return the Swollen Anima Seed to Droman Tashmur in Tirna Vaal.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62187] = { id = 62187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satchel of Culexwood", description = "This lost satchel is filled with wood given by the nearby Culex trees. Fluttercatch would surely appreciate its return.", completion = "A whole sackful?! Wonderful! I'll be sure to put this to good use.", objectives = "Return the Satchel of Culexwood to Fluttercatch in the Banks of Life.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62188] = { id = 62188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch A Star", description = "I require your aid on a... delicate matter, {name}.\n\nStarfly Wings form a vital ingredient for some of our creations and our supply is exhausted.\nThey are tiny things, very fragile, and I am ill able to handle them delicately.\n\nCould you obtain the Starflies for me? They must be caught alive in order for their wings to not spoil and we desperately need them. \n\nI'll ensure that you are compensated for your time, of course.", completion = "Outstanding! I could see the shine coming from your pack before you even arrived.\n\nThank you!", objectives = "Collect 13 Glittering Starflies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62189] = { id = 62189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parasol Components", description = "Sheets of fine cloth, wooden parasol ribs, wooden dowels and metal braces, everything you would need to put together new parasols. These are worth a lot of gold in the Ember Ward. Mats would certainly reward you handsomely if you brought him this cache.", completion = "Oh, wow, this is a real find you have. Here, a heap of Infused Rubies for the bundle, the best you will see here in the ward. And if you see one of my goods you might like, let me know.", objectives = "Return the components to Sanctuary of the Mad.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62190] = { id = 62190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Dirty Job", description = "We gotta fix up this muck pool before we go makin' that dredger butler of yours.\n\nLooks like the anima shortage caused all sorts of problems for this pool.\n\nThem muck pools gotta have plenty of filth and fiber in 'em to grow good dredgers.\n\nBut between them devourers and nasty elementals formin' from all that wild muck, I can't get close enough to feed it!\n\nHelp me out and throw some of that filthy rubble into the pool, yeah?", completion = "I can smell it from here.\n\n<Rendle inhales deeply and sighs.>\n\nHome sweet home.", objectives = "Throw 6 Filthy Rubble into the muck pool.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62194] = { id = 62194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting Words", description = "Throughout the Shadowlands, there is so much magic to learn!\n\nA threat in Bastion has put many of their ancient teachings in danger. I wish to study their scrolls before they are lost forever. We must travel there and safeguard what we can!\n\nHelp me fight back the Forsworn at the Temple of Humility and save the scrolls within.", completion = "You have helped strengthen our forces, Maw Walker.", objectives = "Help Sabrina collect 8 Ancient Teachings and eliminate 8 Forsworn enemies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62195] = { id = 62195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Word", description = "Inquisitor Darksion was an aspiring practitioner of the arcane arts before Denathrius locked her away.\n\nI've heard she will share her knowledge with anyone that releases her from imprisonment.\n\nI want to learn all she knows! We must free her!", progress = "Did we find anything good?", completion = "You have helped strengthen our forces, Maw Walker.", objectives = "Help Sabrina free Inquisitor Darksion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62200] = { id = 62200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Functioning Anima Core", description = "<The incomprehensible core whirs with a pleasant hum. \n\nSurely someone would have a use for this? >", completion = "Thank you for this, {name}. We must conserve all the anima we can.", objectives = "Deliver the Functioning Anima Core to Kalisthene.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62203] = { id = 62203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Major Mirror Disruptions" }
quests[62204] = { id = 62204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Major Mirror Disruptions" }
quests[62205] = { id = 62205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venthyr Ettiquette", progress = "Is that Theotar's new book?", completion = "You know, I really like that Theotar, he knows his stuff and is nice to us even though at times he assumes we can read minds. Silly Venthyr." }
quests[62206] = { id = 62206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ardenweald Etiquette", progress = "Ooh, I am beginning to like these books.", completion = "This one looks fun, I like reading about dreams, and it has pictures!" }
quests[62207] = { id = 62207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bastion Etiquette", progress = "That looks like a 'big' book.", completion = "This seems pretty strict, I am surprised that they come to parties, I think it says here that might not be allowed. Well, I will make sure I memorize it word for word, I am sure they will have already." }
quests[62208] = { id = 62208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maldraxxi Protocols", progress = "It looks shorter than the others, but... are those bullets?", completion = "Not going to lie to you, this sounds really dry. Do I at least get to wear their cool armor?" }
quests[62209] = { id = 62209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Houndmaster Vasanok" }
quests[62210] = { id = 62210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanngror the Torturer" }
quests[62211] = { id = 62211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skittering Broodmother" }
quests[62213] = { id = 62213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brokered Deal", description = "Hey, {name}. I've found a lucrative business proposition that'll help me... us... greatly! See, Au'narim is willing to give us supplies if we can help him recover from a trade deal that went sideways.\n\nApparently, several of his cohorts never returned from a job. He needs us to follow their path and recover the item they failed to deliver. Simple, right?\n\nTo ensure we don't have any mishaps, I've taken the liberty of acquiring a few items that may be of help to us.\n\nSo, you in?", progress = "Did you find the item in question?", completion = "I knew the Maw Walker would deliver.", objectives = "Recover the Broker Bauble.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62214] = { id = 62214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Perdition", description = "Survival requires that we keep our enemies in check, Maw Walker.\n\nWith Gorgoa overflowing, the Mawsworn continue to gain strength.\n\nPerdition Hold has been fortified with fresh troops. We cannot allow the Mawsworn to bolster their ranks any further.\n\nMake your way into Perdition Hold and decimate their forces. When the work is done, you may return to me for your reward.", progress = "I trust the Mawsworn did not trouble you?", completion = "A small victory, Maw Walker. Many more will be required.", objectives = "Kill Mawsworn Troops within Perdition Hold in The Maw.\n\nSuggested Players [3]", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62216] = { id = 62216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training Program", description = "Sergeant Krashj is an adequate drill master, but these recruits need proper training with a real warrior. Someone who has been bloodied on the battlefield. Someone like me!\n\nAnd I know just the fight that will whip these troops into shape.\n\nLet's go teach them a thing or three.", completion = "You two make quite the team. It's good to have dependable comrades in arms.", objectives = "Slay Decadious.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62217] = { id = 62217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Training", description = "Though it was not by our hand, Maldraxxus has dealt a great injustice to the kyrian of Bastion. We must do all that we can to make amends.\n\nThe Forsworn menace continues to be a thorn in their side. Sounds like the perfect opportunity to both show our support and for our recruits to gain some combat experience.", completion = "You and Marz work well together. He'll take the hit whenever you need him to.", objectives = "Eliminate 15 Forsworn forces at The Eternal Forge in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62218] = { id = 62218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fountain for Fae", description = "Nuuminuuru spends their days protecting and taking care of many faeries throughout Ardenweald. They have expressed concern about some faeries in their care whom they have not seen in some time.\n\nReport to Nuuminuuru and see if you can help them find their scattered sprites.", progress = "A greeting to you, ally of the soulbearers.", completion = "A faerie fountain for a rare relaxation... an enticing incentive indeed.", objectives = "Report to Nuuminuuru in Glitterfall Basin in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62219] = { id = 62219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fanciful Distractions", description = "Ever chasing their fleets of fancy, my faerie friends are seldom seen.\n\nTheir mercurial natures oft lead them astray, tracing them paths to distraction and dismay.\n\nSeek my friends, insist they return to my roots, and both you and they may receive recompense.", progress = "My wards know to return to my roost, to spin stories of their pursuits and strengthen their spirits.\n\nThe longer they flit away, the deeper the creases of my concern grow.", completion = "The waters of your realm revitalize my wards in ways those of our home cannot.\n\nOnce again, they return to rest.", objectives = "Find Riverblossom, Lunarwind, and Flitterfly and convince them to return to Nuuminuuru.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62221] = { id = 62221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Own Death Pony!", progress = "That is such a beautiful death pony, ever since I saw my first one I have dreamed of ...", completion = "<Your butler is nearly in tears.>\n\nI get my own death pony to ride? You are the best mortal I have ever met!", objectives = "That is such a beautiful death pony, ever since I saw my first one I have dreamed of...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62222] = { id = 62222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Silver Wings", progress = "What do you intend for me to do with that thing?", completion = "<Your butler is in shock after you tell him he will be flying.>\n\nIf you really need me to follow you around in the air... of course I will do that... please not too high..." }
quests[62223] = { id = 62223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascension Calling: Mikanikos", description = "<While this scroll mimics Kleia's invitation to the Path of Ascension, it is very clearly written in Sika's hand.\n\nIt details an invitation for Mikanikos to participate in the Path, along with Bron.\n\nPerhaps you should bring this to Mikanikos.>", completion = "Me? Take part in the Path of Ascension? What a surprise!\n\nBron and I will participate, of course. The leaps we can achieve in centurion development... Imagine!", objectives = "Inform Mikanikos he is now able to participate in the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62224] = { id = 62224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thread Of Hope", description = "The Court of Night is akin to a thirsty flower, it quickly draws up its nutrients. If well supplied it will bloom and if its supply is depleted, it withers.\n\nOur roots are beginning to dry, we need more anima!\n\nI've sent workers out to place silk lined catchers along the roads and paths that cross Ardenweald. These catchers will collect a tiny bit of anima, not much but enough for what we need.\n\nSeek them out and return the Anima Infused Silk to us.", progress = "Were you able to find the silk?", completion = "Well done. Our leaves lift to the sky in thanks.", objectives = "Collect 13 Anima Infused Silk", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62225] = { id = 62225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bursting the Bubble", description = "<The words of the shadowy herald are dark and foreboding. Whatever \"the Banished One\" intends to accomplish, it must not come to pass.\n\nSomething foul bubbles within the cauldrons nearby. Judging by the care with which the cultists are tending to them, their contents must be crucial to their plans.\n\nSeveral barrels containing what appears to be a new type of plague have been left unattended. Perhaps they can serve as instruments for sabotage.>", progress = "What have you discovered?", completion = "Thank the Light, you have returned unharmed!\n\nWere you able to learn anything about what the cult is doing?", objectives = "Sabotage 3 of the Cult of the Damned's experiments in Mord'rethar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62226] = { id = 62226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talethi's Desire" }
quests[62227] = { id = 62227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xertora's Construct" }
quests[62229] = { id = 62229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashraka's Intelligence" }
quests[62230] = { id = 62230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Stolen Stone Fiend" }
quests[62231] = { id = 62231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Velkein's Blade" }
quests[62232] = { id = 62232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arboreal Tactics", description = "The spriggan of Ardenweald have always been a nuisance. But under Mueh'zala's influence, they could grow into a threat that looms over all of the Shadowlands.\n\nLet's test these troops against a real opponent.", completion = "I see you and Marz have been busy. Job well done, both of you.", objectives = "Eliminate 12 Bristlecone Spriggan in Mistveil Tangle in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62234] = { id = 62234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of the Colossus", description = "I have another task for you, Maw Walker.\n\nDeep within Perdition Hold, there lurks a menacing mechanization known as the Soulsteel Colossus. It must be destroyed before it wreaks havoc upon us.\n\nTravel to the Hold, and then across the bridge into the Altar of Domination. There, casting its vast shadow upon The Maw, you will find the Soulsteel Colossus.\n\nShatter the colossus and bring me its power source as proof of your victory.", progress = "The power source... I trust it was not too heavy?", completion = "The souls trapped within the power core may yet be saved. Leave me to my research, Maw Walker.", objectives = "Retrieve a Colossal Power Core from Perdition Hold in The Maw.\n\nSuggested Players [3]", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62235] = { id = 62235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allay Their Fears" }
quests[62236] = { id = 62236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattlebag's Lost Armor" }
quests[62237] = { id = 62237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Soul Mirror", description = "<A shimmering soul mirror draws your attention on Devos's corpse.\n\nPeculiar that she would keep one on her person. Perhaps Thenios will want to see this.>", progress = "How can I be of service?", completion = "<Thenios studies the mirror closely.>\n\nI see.", objectives = "Bring the Mysterious Soul Mirror to Thenios at the temple in the Eonian Archives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62238] = { id = 62238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Led Astray", description = "Uther was a being of justice on your world. I am sure it was quite surprising for you to see his fate here, following a leader who embodies what he stood against in life.\n\nI believe you should witness this memory firsthand. Take it to my soul mirror. View the memories within.", progress = "Sometimes the hard truths are the most important to witness.", completion = "I hope that this memory helps you to understand Uther's path.", objectives = "Use the Soul Mirror at the Eonian Archives to view Uther's arrival in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62239] = { id = 62239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rodent Removal", description = "<The weapon buzzes with a dark, static energy. Whatever this Mawsworn was testing, it appears to have been somewhat successful on the nearby rodents.\n\nFurther investigation may yield additional information.>", completion = "Serves them right for leaving this unattended.\n\nI am sure we can find other uses for it.", objectives = "Test the Tormentor's Rod on 8 Giant Mawrats in The Beastwarrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62241] = { id = 62241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training Regimen" }
quests[62244] = { id = 62244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging Around", description = "The thin pale ones of Revendreth have been hoarding anima. \n\nI've heard they've been hiding it away, digging holes in the woods and just leaving it there. Anyone could come along and take it.\n\nI say that should be us!\n\nLet's go get some anima.", completion = "Thank you for the supplies. I'll see about setting some aside for you at regular intervals.", objectives = "Collect 15 Lost Anima Caches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62245] = { id = 62245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venari Rep Token Tracking" }
quests[62246] = { id = 62246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fallen Friend", description = "A bracelet delicately woven with living vines falls from Vivanna's wrist as she is slain. In the vines is written, \n\n\"Until Winter's end.\n\n-Flwngyrr\"", completion = "<They take the bracelet from your hand. A minute passes before they speak again.>\n\nHer favorite was Azurebloom Tea.\n\nThank you for bringing this to me.", objectives = "Return this bracelet to Flwngyrr at the Heart of the Forest\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62248] = { id = 62248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venari Rep Token Tracking" }
quests[62249] = { id = 62249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venari Rep Token Tracking" }
quests[62250] = { id = 62250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Adventure Awaits", description = "{name}! You're needed in the present. Things have... well, you should just come back to see.\n\nI would finish what you're doing then head back. I can't keep you in the past for much longer!", completion = "Welcome back to the present! There's a lot you have to do.", objectives = "Return to Stormwind to embark on a new adventure. Chromie's magic will run out when you reach level 70, returning you to Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62256] = { id = 62256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asset Extraction", description = "Hey, it's my good pal {name}! Listen, I'm in a bit of a bind here. I've been trying to negotiate a deal with the broker Au'larrynar and he needs a little something, a job done before he'll accept.\n\nThe deal is he had an associate who went missing with a rare item. He's asked that I... we... locate and return the missing property.\n\nThe associate was last seen in Ardenweald. I know, strange place, way too bright for me. But, I... we... really need this deal to go through! \n\nSo, you ready to go?", progress = "I trust you have held up to your part of the deal?", completion = "Ah, now this is exquisite. Your reconstructed companion said you would be able to come through and you've done so magnificently!\n\nLet him know I'll count this toward the repayment of his debts.", objectives = "Travel to Ardenweald, locate Tabithia, and recover the Otherworldly Egg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62258] = { id = 62258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soaring Over Bastion" }
quests[62259] = { id = 62259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima-Laden Dreamcatcher", description = "You stumble upon an enchanted dreamcatcher, placed so remotely that it has managed to collect a significant amount of anima without being harvested. Droman Dawnblossom in nearby Dreamsong Fenn would surely appreciate its safe return.", completion = "Oh my! How did that get there? No matter. This anima will nurture many souls. Thank you, traveler!", objectives = "Return the Enchanted Dreamcatcher to Droman Dawnblossom in Dreamsong Fenn.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62261] = { id = 62261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grinder", description = "It's tough keeping these hands of mine razor sharp. With all the hacking and cleaving, they can grow dull so quickly! What's a girl to do?\n\nThe House of the Chosen makes some very fine quality sharpening stones. I doubt they will just hand them over, but I'm sure my blades can persuade them otherwise.\n\nHow about we pay them a visit and see how many stones they can spare?", progress = "Did you kill them all?", completion = "I see Guillotine's \"negotiations\" were successful.\n\nThank you, Maw Walker. These sharpening stones will be useful.", objectives = "Collect 12 Sharpening Stones and 3 Bonesheared Grinders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62262] = { id = 62262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungal Feeding", description = "Just as I was making progress on our alternative defense research, my spore samples ran dry!\n\nThe mushrooms I was using can only be found in a particularly unpleasant location to the southeast. To collect an appropriately sized sample, you'll have to--how do I put this--feed them. \n\nDon't ask me why, but apparently, they mature fastest with a nice, rotting corpse nearby.\n\nTry luring a few undead to our fungal friends. That should give 'em all the nutrients they need to grow big and strong.", progress = "Any luck with those samples?", completion = "Oh, these are just lovely!\n\nI hope you didn't get your hands too dirty.", objectives = "Collect 20 Mature Spore Samples from Gloomshrooms in Scourgeholme.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62263] = { id = 62263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", progress = "I feel a breeze on the other side. I guess that means it's not underground.", completion = "Must be nice to have the leisure to just sit and think all the time. \n\nI've barely got time myself, with all the work I have keeping this place together!\n\nStill, that was nice of you to help out the old turtle.", objectives = "Investigate the unknown area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62265] = { id = 62265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Adventure Awaits", description = "{name}! You're needed in the present. Things have... well, you should just come back to see.\n\nI would finish what you're doing then head back. I can't keep you in the past for much longer!", completion = "Welcome back to the present! There's a lot you have to do.", objectives = "Return to Orgrimmar to embark on a new adventure. Chromie's magic will run out when you reach level 70, returning you to Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62275] = { id = 62275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bastion", description = "After being set back by a surprise attack by Maldraxxus forces and an army of their own fallen kin known as the Forsworn, the Ascended stand to lose control of Bastion if they are not given aid.", completion = "Bastion is in dire need of your aid.", objectives = "Speak with Tal-Inara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62276] = { id = 62276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drink to the Dead", description = "The Forsworn are ravaging the temples of Bastion, and the aspirants are leaving behind their supplies as they flee.\n\nAll those wonderful bottles of nectar falling into the hands of the Forsworn? I think not! \n\nThere's no way we can save all of the aspirants, but we can keep the Forsworn from taking those supplies. Besides... we could all use something to drink around here.", progress = "Did you find us some supplies?", completion = "Uh, I see you brought back a few friends?", objectives = "24 Purified Nectar and 2 Stewards collected", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62277] = { id = 62277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ardenweald", description = "Ardenweald still faces threats from the Drust, as well as other nefarious forces.\n\nThe Winter Queen could use your aid in fending off the forces that seek to destroy Ardenweald.", completion = "Ardenweald would be most appreciative of your help.", objectives = "Speak with Tal-Inara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62278] = { id = 62278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maldraxxus", description = "With the houses in shambles, the loyal army of the Primus struggles to hold their ground in Maldraxxus.\n\nThey need help to tip the scales in their favor.", completion = "The armies loyal to the Primus need your aid.", objectives = "Speak with Tal-Inara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62279] = { id = 62279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revendreth", description = "Chaos rules Revendreth in the wake of Sire Denathrius's betrayal. \n\nThey are in dire need of your aid!", completion = "Revendreth would be most grateful for your aid.", objectives = "Speak with Tal-Inara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62280] = { id = 62280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Limbo" }
quests[62284] = { id = 62284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observing Battle", description = "It is clear that you mortals thrive on conflict. Members of my cartel have a keen interest in observing your combat prowess in action.\n\nYou seem to be fond of squabbling over contested ground. Observing such territorial behavior would benefit me, and could provide opportunities for you as well.\n\nCan I count on your participation?", progress = "Observation in progress.", completion = "Excellent. You fight so fiercely to claim a piece of ground. The Observer will find that intriguing.", objectives = "Obtain Honor in Random Battlegrounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62285] = { id = 62285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observing War", description = "Your appetite for conflict is a subject of much discussion here in Oribos, mortal. Members of my cartel have a keen interest in observing your combat prowess in action.\n\nThough I understand a great war recently concluded on your world, I am told large-scale conflicts continue to play out in certain locations.\n\nAny chance you could arrange a demonstration?", progress = "Observation in progress.", completion = "A most enlightening conflict. The Observer will be pleased.", objectives = "Obtain Honor in Epic Battlegrounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62286] = { id = 62286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observing Skirmishes", description = "Fascinating how much entertainment your kind draws from conflict, mortal. Members of my cartel have a keen interest in observing your combat prowess in action.\n\nI am told that small-scale skirmishes allow your greatest champions to demonstrate their martial superiority over their rivals. No doubt my people would learn much from observing such a contest.\n\nMight I have the honor of a demonstration?", progress = "Observation in progress.", completion = "Fascinating. Fascinating indeed. The Observer will be pleased.", objectives = "Obtain Honor from Arena Skirmishes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62287] = { id = 62287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observing Arenas", description = "The denizens of your world seem to thrive on conflict, mortal. Members of my cartel have a keen interest in observing your combat prowess in action.\n\nSmall-scale encounters in a constrained setting could prove informative for me, and potentially lucrative for you.\n\nWhat do you say?", progress = "Observation in progress.", completion = "I do so enjoy the completion of a successful arrangement! The Observer will be pleased.", objectives = "Obtain Honor in Arenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62288] = { id = 62288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observing Teamwork", description = "It's truly fascinating how conflict drives your kind, mortal. Members of my cartel have a keen interest in observing your combat prowess in action.\n\nI am told that some of your most impressive martial demonstrations involve combat between predetermined teams. My people are unfamiliar with such contests.\n\nWould you be willing to offer a demonstration?", progress = "Observation in progress.", completion = "Our arrangement allowed me to gather some very useful information. The Observer will be pleased.", objectives = "Obtain Honor in Rated Battlegrounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62291] = { id = 62291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venari Rep Token Tracking" }
quests[62292] = { id = 62292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pitch Black Scourgestones", progress = "The most powerful of the undead carry scourgestones imbued with the darkest magic. \n\nWe do not know from whence they came, but their power is unlike any we have encountered before. \n\nPlease relinquish any you find to the Argent Crusade. Who knows what foul evil may be lurking within them?", completion = "We will study these stones at once and seal them away. They bring me unease." }
quests[62293] = { id = 62293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkened Scourgestones", progress = "Scourgestones were once common amongst the minions of the Lich King. But these new ones are different... and darker.\n\nBring them to us as you find them. They will serve both a mark of your victories, and as an opportunity for us to study their strange magic.", completion = "We prevailed against the undead before, and we shall do so again! For the Light!" }
quests[62294] = { id = 62294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Lich's Trash...", description = "It is said that one person's trash, is another's treasure. When it comes to relics, the adage is particularly true.\n\nThe House of Rituals is notoriously secretive, which means any knowledge we can glean from them will be all the sweeter.\n\nIf we sift through their detritus, I'm sure there are all sorts of treasures we will find.", progress = "Did you find anything of interest?", completion = "This is simply marvelous! This will provide some excellent insight into the history of Margrave Sin'dane... and possibly something we can use to our own benefit later on.", objectives = "Search through Piles of Debris within the House of Rituals for clues about its past, and recover an Intriguing Ancient Relic.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62295] = { id = 62295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning Out the Vault", description = "The Scourge's rampant aggression has proven difficult to predict, even for us.\n\nBy the time we knew they were upon us, it was too late.\n\nWith our forces spread thin, we are left with what you see before you.\n\nEnter the vault. Slay our enemies where they stand.\n\nSoon the Shadow Vault will be ours once more.", objectives = "Purge the Shadow Vault of the Scourge presence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62296] = { id = 62296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Unknown", description = "Come to pay old Marasmius a visit? I have a special task for you.\n\nOne of my shoots has found a strange place, a place even I've never seen before.\n\nI'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for!\n\nWhat do you say, {name}? Up for an adventure?", progress = "Keep your guard up. It could lead anywhere!", completion = "That was close. Those pests can quickly blast away whole chunks of Ardenweald if we aren't careful. We've got enough problems on our hands as it is!", objectives = "Investigate the unknown area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62297] = { id = 62297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fatal Failure", description = "Acolyte, we could use a hand here!\n\nIt seems one of your fellow pupils botched their ritual in spectacular fashion. Now destructive necromantic energies are running rampant throughout the house.\n\nThis threat must be dealt with. Can you assist?", progress = "Have you taken care of the threat, acolyte?", completion = "Well done, acolyte. The rest should dissipate with time.\n\nTake this, it was left behind by the feckless adept that created this mess. I hope you will put it to better use.", objectives = "Kill 7 Fatal Coalescences in the House of Rituals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62298] = { id = 62298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Classic 20-49" }
