quests[62305] = { id = 62305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 2" }
quests[62307] = { id = 62307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 3" }
quests[62308] = { id = 62308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantle of Mastery", description = "You have done much to establish yourself as a promising acolyte. Your superiors have made it known that you are ready to be tested for your ritualist's mantle. \n\nWhen you are ready, begin the Ritual of Ancient Summoning to call forth an elder spirit of Maldraxxus. Conquer the spirit, and prove your mettle!", completion = "You have proven yourself worthy to don the mantle, acolyte.\n\nWear it with honor and pride.", objectives = "Summon an elder spirit of Maldraxxus through the Prime Arcanum and defeat it. Summoning requires three players.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62309] = { id = 62309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Secutor Mevix", objectives = "{name}, it is good to see you again!\n\nFollowing your success against the House of Constructs, Secutor Mevix is eager for more action on the battlefield.\n\nDon't leave an eager soldier to wallow here. Give him purpose!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
